def count_errors(path):
    count = 0
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "ERROR" in line:
                count += 1
    return count

with open("kakade_demo.log", "w", encoding="utf-8") as f:
    f.writelines(["INFO ok\n", "ERROR bad\n", "ERROR fail\n"])
print(count_errors("kakade_demo.log"))
